      while (len > left_length) {
        if (net_write_packet(net, packet, left_length)) return true;
        packet += left_length;
        len -= left_length;
      }
    }
    if (len > net->max_packet) return net_write_packet(net, packet, len);
    /* Send out rest of the blocks as full sized blocks */
